import{_ as t,c as a,b as s,a2 as r}from"./chunks/framework.BEqfOpL-.js";const o="/images/editorial_presence.webp",m=JSON.parse('{"title":"My Placements","description":"My Placements shows where PodSEO has found your podcast across platforms and the web. Start with the summary at the top, then open the sections that have results for your show.","frontmatter":{},"headers":[],"relativePath":"features/my-placements.md","filePath":"features/my-placements.md"}'),i={name:"features/my-placements.md"};function n(l,e,d,h,c,u){return s(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="my-placements" tabindex="-1">My Placements <a class="header-anchor" href="#my-placements" aria-label="Permalink to &quot;My Placements&quot;">​</a></h1><h2 id="track-where-your-podcast-gets-featured" tabindex="-1">Track Where Your Podcast Gets Featured <a class="header-anchor" href="#track-where-your-podcast-gets-featured" aria-label="Permalink to &quot;Track Where Your Podcast Gets Featured&quot;">​</a></h2><p>My Placements shows where PodSEO has found your podcast across platforms and the web. Start with the summary at the top, then open the sections that have results for your show.</p><p><a href="/images/editorial_presence.webp" title="Open screenshot at full size"><img src="'+o+'" alt="My Placements summary, editorial lists, and sponsored placements" width="600px" style="display:block;margin:0 auto;"></a></p><p><strong>To access:</strong> <strong>Promote → PR Outreach</strong>, then the <strong>Placements</strong> tab.</p><h2 id="what-you-ll-see" tabindex="-1">What You&#39;ll See <a class="header-anchor" href="#what-you-ll-see" aria-label="Permalink to &quot;What You&#39;ll See&quot;">​</a></h2><h3 id="editorial-lists" tabindex="-1">Editorial Lists <a class="header-anchor" href="#editorial-lists" aria-label="Permalink to &quot;Editorial Lists&quot;">​</a></h3><p>Track your podcast&#39;s appearances in curated editorial content across:</p><ul><li><strong>Apple Podcasts</strong> - New &amp; Noteworthy, editorial collections, category features</li><li><strong>Spotify</strong> - Editorial playlists, featured sections, genre highlights</li><li><strong>Amazon Music</strong> - Curated recommendations and platform features</li><li><strong>YouTube Music</strong> - Featured podcast placements</li><li><strong>Pocket Casts</strong> - Features recorded on the Pocket Casts Discover page</li></ul><p><strong>Editorial lists</strong> shows the lists that feature your show today. <strong>Previously observed</strong> shows appearances PodSEO recorded in the last 30 days that are no longer current.</p><h3 id="sponsored-placements" tabindex="-1">Sponsored Placements <a class="header-anchor" href="#sponsored-placements" aria-label="Permalink to &quot;Sponsored Placements&quot;">​</a></h3><p><strong>Sponsored placements</strong> shows paid appearances PodSEO detected. <strong>First observed</strong> and <strong>Last observed</strong> tell you when PodSEO saw a placement. Expand <strong>Observation history</strong> when available to see the individual periods PodSEO recorded.</p><h3 id="best-of-lists-and-web-links" tabindex="-1">Best-of Lists and Web Links <a class="header-anchor" href="#best-of-lists-and-web-links" aria-label="Permalink to &quot;Best-of Lists and Web Links&quot;">​</a></h3><p><strong>Best-of lists</strong> shows ranked roundups that include your show. <strong>Web links</strong> shows linked coverage in places like blogs, newsletters, and publications. <strong>Directory &amp; app listings</strong> is expandable when PodSEO finds pages where people can look up or play your show. The coverage counts reflect editorial and linked coverage.</p><p>The summary shows how many pages link to your show and how many sites they come from. Each web-link row shows its source, with an authority label when available. <strong>Cited in AI answers</strong> identifies a page an AI assistant has cited. See <a href="/features/ai-mentions.html">AI Mentions</a> for details.</p><p>Use <strong>Add a link we missed</strong> when it appears to submit a page that mentions your podcast. If a result belongs to a different show, choose <strong>Not my show</strong> on the row.</p><h2 id="understanding-the-metrics" tabindex="-1">Understanding the Metrics <a class="header-anchor" href="#understanding-the-metrics" aria-label="Permalink to &quot;Understanding the Metrics&quot;">​</a></h2><h3 id="domain-authority" tabindex="-1">Domain Authority <a class="header-anchor" href="#domain-authority" aria-label="Permalink to &quot;Domain Authority&quot;">​</a></h3><p>Web links are categorized by domain authority:</p><ul><li><strong>Very High</strong> - Major publications, well-known podcasting sites</li><li><strong>High</strong> - Established blogs, industry newsletters, respected directories</li><li><strong>Medium</strong> - Smaller sites, niche publications, personal recommendations</li></ul><p>Higher authority sources carry more weight for discoverability and credibility.</p><h2 id="strategic-applications" tabindex="-1">Strategic Applications <a class="header-anchor" href="#strategic-applications" aria-label="Permalink to &quot;Strategic Applications&quot;">​</a></h2><h3 id="measure-editorial-success" tabindex="-1">Measure Editorial Success <a class="header-anchor" href="#measure-editorial-success" aria-label="Permalink to &quot;Measure Editorial Success&quot;">​</a></h3><p>Track your editorial presence over time to understand:</p><ul><li>Which platforms feature you most often</li><li>How long your editorial placements typically last</li><li>Whether your editorial visibility is growing</li></ul><h3 id="identify-patterns" tabindex="-1">Identify Patterns <a class="header-anchor" href="#identify-patterns" aria-label="Permalink to &quot;Identify Patterns&quot;">​</a></h3><p>Analyze your editorial history to spot patterns:</p><ul><li>Content types or themes that attract editorial attention</li><li>Timing patterns (seasonal trends, launch momentum)</li><li>Platforms where you have the strongest editorial relationship</li></ul><h3 id="build-on-web-links" tabindex="-1">Build on Web Links <a class="header-anchor" href="#build-on-web-links" aria-label="Permalink to &quot;Build on Web Links&quot;">​</a></h3><p>Use web link data to:</p><ul><li>Discover sites that feature podcasts like yours</li><li>Reach out to publications that already know your show</li><li>Prioritize outreach to high-authority domains</li></ul><h2 id="requesting-editorial-features" tabindex="-1">Requesting Editorial Features <a class="header-anchor" href="#requesting-editorial-features" aria-label="Permalink to &quot;Requesting Editorial Features&quot;">​</a></h2><p>If you want to increase your editorial presence, you can use PodSEO&#39;s <a href="/features/pr-outreach.html">PR Outreach</a> pipeline to manage the process. Click <strong>Find Opportunities</strong> in PR Outreach to load a curated list of pitch targets — platform editorial submission pages (such as Apple Podcasts and Spotify) along with podcast newsletters, directories, and blogs worth pitching — then add them to your kanban board and track your submissions through the pipeline stages from Identified to Featured.</p><p>For Apple Podcasts specifically:</p><ol><li>Visit Apple&#39;s <a href="https://airtable.com/appL7FlZuT3KbtUz0/pagX0sfhAxqSB6zp4/form" target="_blank" rel="noreferrer">feature request form</a></li><li>Follow their <a href="https://podcasters.apple.com/support/1993-optimize-your-request-for-promotion" target="_blank" rel="noreferrer">optimization guide</a></li><li>Submit at least 2 weeks before your desired feature date</li><li>Prepare special <a href="https://podcasters.apple.com/asset/show-hero-template.zip" target="_blank" rel="noreferrer">feature artwork</a> if required</li></ol><p>Tips for successful requests:</p><ul><li>Highlight what makes your content unique and timely</li><li>Explain your promotional plans to amplify the feature</li><li>Ensure your podcast meets platform quality standards</li><li>Consider timing around significant episodes or milestones</li></ul><h2 id="connection-to-other-features" tabindex="-1">Connection to Other Features <a class="header-anchor" href="#connection-to-other-features" aria-label="Permalink to &quot;Connection to Other Features&quot;">​</a></h2><p>My Placements works alongside other PodSEO discovery features:</p><ul><li><strong><a href="/features/pr-outreach.html">PR Outreach</a></strong> - Manage opportunities to earn relevant web mentions and listicle placements</li><li><strong><a href="/features/ai-mentions.html">AI Mentions</a></strong> - Track AI recommendation visibility and explore sources cited by assistants</li><li><strong>Curated Lists</strong> - Browse what platforms are promoting across all podcasts</li><li><strong>All Charts</strong> - Monitor chart rankings for another view of platform visibility</li></ul><h2 id="availability" tabindex="-1">Availability <a class="header-anchor" href="#availability" aria-label="Permalink to &quot;Availability&quot;">​</a></h2><p>Platform editorial tracking is available to all users. Web links with domain authority data are available on paid plans (Podcaster, Producer, and Agency).</p><p><strong>Related Features</strong>: Use <a href="/features/curated-lists.html">Curated Lists</a> to research platform editorial content, and check <a href="/features/all-charts.html">All Charts</a> to see chart rankings alongside editorial visibility.</p>',43)])])}const g=t(i,[["render",n]]);export{m as __pageData,g as default};
